CREATE OR REPLACE FUNCTION private.apply_worker_personnel_payload(p_worker_id uuid, p_payload jsonb, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_company uuid;
  v_family jsonb;
  v_member jsonb;
  v_birth date;
  v_name text;
  v_relation text;
begin
  select w.company_id into v_company
  from public.workers w
  where w.id=p_worker_id
  for update;

  if v_company is null then raise exception '社員を確認できません'; end if;

  update public.workers
  set name=coalesce(nullif(trim(p_payload->>'name'),''),name),
      role=nullif(trim(coalesce(p_payload->>'role','')),''),
      phone=nullif(trim(coalesce(p_payload->>'phone','')),''),
      updated_at=now()
  where id=p_worker_id;

  insert into public.worker_personnel_profiles(
    worker_id,company_id,blood_type,address,
    emergency_name,emergency_relation,emergency_phone,emergency_address,
    family_composition,
    created_by,updated_by,updated_at
  )
  values(
    p_worker_id,v_company,
    nullif(trim(coalesce(p_payload->>'blood_type','')),''),
    nullif(trim(coalesce(p_payload->>'address','')),''),
    nullif(trim(coalesce(p_payload->>'emergency_name','')),''),
    nullif(trim(coalesce(p_payload->>'emergency_relation','')),''),
    nullif(trim(coalesce(p_payload->>'emergency_phone','')),''),
    nullif(trim(coalesce(p_payload->>'emergency_address','')),''),
    nullif(trim(coalesce(p_payload->>'family_composition','')),''),
    p_actor,p_actor,now()
  )
  on conflict(worker_id) do update
  set blood_type=excluded.blood_type,
      address=excluded.address,
      emergency_name=excluded.emergency_name,
      emergency_relation=excluded.emergency_relation,
      emergency_phone=excluded.emergency_phone,
      emergency_address=excluded.emergency_address,
      family_composition=excluded.family_composition,
      updated_by=excluded.updated_by,
      updated_at=now();

  v_family:=coalesce(p_payload->'family_members','[]'::jsonb);
  if jsonb_typeof(v_family)<>'array' then
    raise exception '家族構成データを確認してください';
  end if;

  delete from public.worker_family_members
  where worker_id=p_worker_id and company_id=v_company;

  for v_member in
    select value from jsonb_array_elements(v_family)
  loop
    v_name:=trim(coalesce(v_member->>'name',''));
    v_relation:=trim(coalesce(v_member->>'relation',''));
    if v_name='' or v_relation='' then
      raise exception '家族の氏名と続柄を入力してください';
    end if;

    begin
      v_birth:=nullif(v_member->>'birth_date','')::date;
    exception when others then
      raise exception '家族の誕生日を確認してください';
    end;

    insert into public.worker_family_members(
      company_id,worker_id,name,relation,birth_date,is_dependent,
      created_by,updated_by
    )
    values(
      v_company,p_worker_id,v_name,v_relation,v_birth,
      coalesce((v_member->>'is_dependent')::boolean,false),
      p_actor,p_actor
    );
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION private.confirm_payroll_review_month(p_period_start date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  uid uuid:=auth.uid();
  cid uuid;
  role_text text;
  v_period_start date:=date_trunc('month',p_period_start)::date;
  expected_count integer;
  checked_count integer;
  changed integer;
begin
  if uid is null then raise exception 'ログインが必要です'; end if;
  if p_period_start is null then raise exception '対象月を確認してください'; end if;

  select cm.company_id,cm.role::text
  into cid,role_text
  from public.company_members cm
  where cm.user_id=uid
  limit 1;

  if cid is null or role_text<>'viewer' then
    raise exception '閲覧者のみ給与確認を確定できます';
  end if;

  select count(*)
  into expected_count
  from public.payroll_statements ps
  join public.workers w
    on w.id=ps.worker_id and w.company_id=ps.company_id
  where ps.company_id=cid
    and ps.period_start=v_period_start
    and w.affiliation::text='employee';

  if expected_count=0 then
    raise exception 'この月の給与明細がありません';
  end if;

  select count(*)
  into checked_count
  from public.payroll_statements ps
  join public.workers w
    on w.id=ps.worker_id and w.company_id=ps.company_id
  join public.payroll_statement_reviews r
    on r.statement_id=ps.id
   and r.reviewer_id=uid
   and r.checked_revision=ps.revision
  where ps.company_id=cid
    and ps.period_start=v_period_start
    and w.affiliation::text='employee';

  if checked_count<>expected_count then
    raise exception '全従業員の給与明細を確認してから確定してください';
  end if;

  update public.payroll_statement_reviews r
  set confirmed_revision=ps.revision,
      confirmed_at=now(),
      updated_at=now()
  from public.payroll_statements ps
  join public.workers w
    on w.id=ps.worker_id and w.company_id=ps.company_id
  where r.statement_id=ps.id
    and r.reviewer_id=uid
    and ps.company_id=cid
    and ps.period_start=v_period_start
    and w.affiliation::text='employee'
    and r.checked_revision=ps.revision;

  get diagnostics changed=row_count;
  return changed;
end;
$function$

CREATE OR REPLACE FUNCTION private.finalize_payroll_review(p_period_start date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); cid uuid; role_text text; missing_count integer; statement_count integer;
begin
  select cm.company_id,cm.role::text into cid,role_text from public.company_members cm where cm.user_id=uid limit 1;
  if cid is null or role_text<>'viewer' then raise exception '閲覧者のみ最終確定できます'; end if;
  select count(*) into statement_count from public.payroll_statements ps join public.workers w on w.id=ps.worker_id and w.company_id=ps.company_id
    where ps.company_id=cid and ps.period_start=p_period_start and w.affiliation::text='employee';
  if statement_count=0 then raise exception '確認対象の給与明細がありません'; end if;
  select count(*) into missing_count
  from public.payroll_statements ps join public.workers w on w.id=ps.worker_id and w.company_id=ps.company_id
  left join public.payroll_statement_reviews rv on rv.statement_id=ps.id and rv.reviewer_id=uid
  where ps.company_id=cid and ps.period_start=p_period_start and w.affiliation::text='employee'
    and rv.checked_revision is distinct from ps.revision;
  if missing_count>0 then raise exception '全従業員の給与明細を確認してから確定してください'; end if;
  update public.payroll_statement_reviews rv
    set confirmed_revision=ps.revision,confirmed_at=now(),updated_at=now()
  from public.payroll_statements ps join public.workers w on w.id=ps.worker_id and w.company_id=ps.company_id
  where rv.statement_id=ps.id and rv.reviewer_id=uid and ps.company_id=cid and ps.period_start=p_period_start
    and w.affiliation::text='employee' and rv.checked_revision=ps.revision;
end $function$

CREATE OR REPLACE FUNCTION private.set_payroll_review_check(p_statement_id uuid, p_revision integer, p_checked boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); cid uuid; role_text text; current_revision integer; statement_cid uuid;
begin
  select cm.company_id,cm.role::text into cid,role_text from public.company_members cm where cm.user_id=uid limit 1;
  if cid is null or role_text<>'viewer' then raise exception '閲覧者のみ確認チェックを変更できます'; end if;
  select ps.company_id,ps.revision into statement_cid,current_revision from public.payroll_statements ps where ps.id=p_statement_id;
  if statement_cid is distinct from cid or current_revision is null then raise exception '給与明細が見つかりません'; end if;
  if current_revision is distinct from p_revision then raise exception '給与明細が更新されています。一覧を再読み込みしてください'; end if;
  insert into public.payroll_statement_reviews(company_id,statement_id,reviewer_id,checked_revision,checked_at,confirmed_revision,confirmed_at,updated_at)
  values(cid,p_statement_id,uid,case when p_checked then current_revision end,case when p_checked then now() end,null,null,now())
  on conflict(statement_id,reviewer_id) do update set
    checked_revision=case when p_checked then current_revision end,
    checked_at=case when p_checked then now() end,confirmed_revision=null,confirmed_at=null,updated_at=now();
end $function$

CREATE OR REPLACE FUNCTION public.current_worker_personnel_profile()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_worker uuid;
begin
  select w.id into v_worker
  from public.workers w
  where w.user_id=auth.uid()
  limit 1;

  if v_worker is null then
    return null;
  end if;

  return private.worker_personnel_payload(v_worker)
    || jsonb_build_object('worker_id',v_worker);
end
$function$

CREATE OR REPLACE FUNCTION public.save_worker_personnel_profile(p_worker_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_company uuid;
  v_existing boolean;
  v_request uuid;
  v_current jsonb;
  v_actor uuid:=auth.uid();
  v_actor_role text;
  v_required integer;
begin
  if v_actor is null then raise exception 'ログインが必要です'; end if;
  if not private.can_edit_worker_personnel(p_worker_id) then
    raise exception '社員個人情報を変更する権限がありません';
  end if;

  select w.company_id into v_company
  from public.workers w
  where w.id=p_worker_id;

  if v_company is null then raise exception '社員を確認できません'; end if;

  select cm.role::text into v_actor_role
  from public.company_members cm
  where cm.company_id=v_company
    and cm.user_id=v_actor
  limit 1;

  if v_actor_role is null then
    raise exception '会社への所属が必要です';
  end if;

  select exists(
    select 1
    from public.worker_personnel_profiles p
    where p.worker_id=p_worker_id
  ) into v_existing;

  v_current:=private.worker_personnel_payload(p_worker_id);

  if not v_existing then
    perform private.apply_worker_personnel_payload(p_worker_id,p_payload,v_actor);
    return jsonb_build_object(
      'status','saved',
      'requires_approval',false,
      'saved_directly',true
    );
  end if;

  if v_current=p_payload then
    return jsonb_build_object(
      'status','unchanged',
      'requires_approval',false,
      'saved_directly',false
    );
  end if;

  -- Company owners/admins can directly register or update employee personnel
  -- information. Sub-admin/manager edits keep the approval workflow.
  if v_actor_role in ('owner','admin') then
    perform private.apply_worker_personnel_payload(p_worker_id,p_payload,v_actor);

    update public.worker_personnel_change_requests
    set status='rejected',resolved_at=now()
    where worker_id=p_worker_id
      and status='pending';

    return jsonb_build_object(
      'status','saved',
      'requires_approval',false,
      'saved_directly',true
    );
  end if;

  select count(*)::integer into v_required
  from public.worker_personnel_approvers a
  where a.company_id=v_company
    and a.user_id<>v_actor;

  if v_required<1 then
    raise exception '社員個人情報の承認者を1〜3名で設定してください（申請者本人は承認できません）';
  end if;

  v_required:=least(v_required,3);

  update public.worker_personnel_change_requests
  set status='rejected',resolved_at=now()
  where worker_id=p_worker_id
    and requested_by=v_actor
    and status='pending';

  insert into public.worker_personnel_change_requests(
    company_id,worker_id,requested_by,proposed,required_approvals
  ) values(v_company,p_worker_id,v_actor,p_payload,v_required)
  returning id into v_request;

  insert into public.app_notifications(
    company_id,recipient_user_id,kind,title,body,action_key,action_id
  )
  select v_company,a.user_id,'approval','社員個人情報の変更申請',
    '社員個人情報の変更申請があります。登録済み承認者の承認後に反映されます。',
    'worker_personnel_change',v_request
  from public.worker_personnel_approvers a
  where a.company_id=v_company
    and a.user_id<>v_actor;

  return jsonb_build_object(
    'status','pending',
    'requires_approval',true,
    'request_id',v_request,
    'required_approvals',v_required,
    'saved_directly',false
  );
end
$function$
